import { Provider } from '@ethersproject/abstract-provider';
import { BigNumber } from 'ethers';
import { ProviderLike } from './types';
export type L1Provider<TProvider extends Provider> = TProvider & {
    estimateCrossDomainMessageFee(l1Provider: ProviderLike, sender: string, gasLimit: bigint | BigNumber | number): Promise<BigNumber>;
    _isL1Provider: true;
};
